cat > UITests.swift <<'EOF'
import XCTest
final class SimTapUITests: XCTestCase {
    func testOpenAttachmentMenu() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let attach = app.buttons["AttachButton"]
        if !attach.waitForExistence(timeout: 3) {
            let room = app.staticTexts.matching(NSPredicate(format: "label == %@", "Weekend Plans")).firstMatch
            XCTAssertTrue(room.waitForExistence(timeout: 10), "Weekend Plans room is not visible")
            room.tap()
        }
        XCTAssertTrue(attach.waitForExistence(timeout: 10), "Attachment button is not visible")
        attach.tap()
        sleep(2)
        print("ELEMENT_HIERARCHY_START")
        print(app.debugDescription)
        print("ELEMENT_HIERARCHY_END")
    }
}
EOF
xcodebuild test -quiet -project SimTap.xcodeproj -scheme SimTapUITests -destination 'platform=iOS Simulator,id=1F235E3C-7A49-469B-BD55-A215D50E4A10' -derivedDataPath DerivedData CODE_SIGNING_ALLOWED=NO

